import { useState, type FormEvent } from 'react';
import { JxButton, JxInputField, JxSelect, JxSwitch, JxToast } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const ROLE_OPTIONS = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'только чтение' },
  { value: 'editor', label: 'Редактор', meta: 'правки и комментарии' },
  { value: 'admin', label: 'Администратор', meta: 'полный доступ' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const isValid = EMAIL_PATTERN.test(email.trim());
  const errorText = touched && !isValid ? 'Введите адрес вида name@company.com' : undefined;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!isValid) return;
    setInvitedEmail(email.trim());
    setEmail('');
    setTouched(false);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16, maxWidth: 420 }}>
      {invitedEmail && (
        <JxToast
          variant="success"
          title="Приглашение отправлено"
          message={`Мы позвали ${invitedEmail} в команду.`}
          onClose={() => setInvitedEmail(null)}
        />
      )}

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          name="email"
          required
          placeholder="name@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          onBlur={() => setTouched(true)}
          helperText="Приглашение действует 7 дней"
          errorText={errorText}
        />

        <JxSelect
          label="Роль в команде"
          placeholder="Выберите роль"
          options={ROLE_OPTIONS}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление на почту"
          name="notify"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <div style={{ display: 'flex', gap: 8 }}>
          <JxButton type="submit" variant="primary" disabled={!isValid}>
            Отправить приглашение
          </JxButton>
        </div>
      </form>
    </div>
  );
}

